class Solution:
    def getSum(self, nums: list[int]) -> int:
        MOD = 1_000_000_007

        def calc(arr: list[int]) -> int:
            f = {}
            g = {}
            ans = 0
            for v in arr:
                # Sequences of length >= 2 ending at v by extending v - 1
                cnt = f.get(v - 1, 0)
                sum_val = (g.get(v - 1, 0) + cnt * v) % MOD
                ans = (ans + sum_val) % MOD

                # Update tables for v: include sequences extending v - 1, plus single element v
                f[v] = (f.get(v, 0) + cnt + 1) % MOD
                g[v] = (g.get(v, 0) + sum_val + v) % MOD
            return ans

        x = calc(nums)
        y = calc(nums[::-1])
        s = sum(nums) % MOD

        return (x + y + s) % MOD

#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int getSum(std::vector<int>& nums) {
        long long MOD = 1000000007;

        auto calc = [&](const std::vector<int>& arr) {
            std::unordered_map<int, long long> f, g;
            long long ans = 0;
            for (int v : arr) {
                long long cnt = f.count(v - 1) ? f[v - 1] : 0;
                long long sum_val = ((g.count(v - 1) ? g[v - 1] : 0) + cnt * v) % MOD;
                ans = (ans + sum_val) % MOD;

                f[v] = (f[v] + cnt + 1) % MOD;
                g[v] = (g[v] + sum_val + v) % MOD;
            }
            return ans;
        };

        long long x = calc(nums);
        std::vector<int> rev_nums = nums;
        std::reverse(rev_nums.begin(), rev_nums.end());
        long long y = calc(rev_nums);

        long long s = 0;
        for (int v : nums) s = (s + v) % MOD;

        return (x + y + s) % MOD;
    }
};

import java.util.*;

class Solution {
    private final int MOD = 1_000_000_007;

    public int getSum(int[] nums) {
        long x = calc(nums);
        int n = nums.length;
        int[] rev = new int[n];
        for (int i = 0; i < n; i++) rev[i] = nums[n - 1 - i];
        long y = calc(rev);

        long s = 0;
        for (int v : nums) s = (s + v) % MOD;

        return (int) ((x + y + s) % MOD);
    }

    private long calc(int[] arr) {
        Map<Integer, Long> f = new HashMap<>();
        Map<Integer, Long> g = new HashMap<>();
        long ans = 0;

        for (int v : arr) {
            long cnt = f.getOrDefault(v - 1, 0L);
            long sumVal = (g.getOrDefault(v - 1, 0L) + cnt * v) % MOD;
            ans = (ans + sumVal) % MOD;

            f.put(v, (f.getOrDefault(v, 0L) + cnt + 1) % MOD);
            g.put(v, (g.getOrDefault(v, 0L) + sumVal + v) % MOD);
        }
        return ans;
    }
}

var getSum = function(nums) {
    const MOD = 1000000007n;

    function calc(arr) {
        const f = new Map();
        const g = new Map();
        let ans = 0n;

        for (const val of arr) {
            const v = BigInt(val);
            const prev = Number(v - 1n);
            const currKey = Number(v);

            const cnt = f.get(prev) || 0n;
            const prevSum = g.get(prev) || 0n;
            const sumVal = (prevSum + cnt * v) % MOD;
            ans = (ans + sumVal) % MOD;

            f.set(currKey, ((f.get(currKey) || 0n) + cnt + 1n) % MOD);
            g.set(currKey, ((g.get(currKey) || 0n) + sumVal + v) % MOD);
        }
        return ans;
    }

    const x = calc(nums);
    const rev = [...nums].reverse();
    const y = calc(rev);

    let s = 0n;
    for (const v of nums) s = (s + BigInt(v)) % MOD;

    return Number((x + y + s) % MOD);
};
